<?php
require_once 'config.php';require_login();$pdo=db();$page_title='Inventory';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$agent=(int)($_POST['agent_id']??0);$kg=(float)($_POST['package_kg']??0);$qty=(int)($_POST['quantity']??0);$date=$_POST['released_at']??date('Y-m-d');if($agent<1||!in_array($kg,[1.0,5.0,20.0],true)||$qty<1)throw new RuntimeException('Choose an agent, package size, and quantity greater than zero.');$stmt=$pdo->prepare("INSERT INTO inventory_releases(agent_id,package_kg,quantity,released_at,notes) VALUES(?,?,?,?,?)");$stmt->execute([$agent,$kg,$qty,$date,trim($_POST['notes']??'')]);redirect('inventory.php');}catch(Throwable $ex){$error=$ex instanceof RuntimeException?$ex->getMessage():'Unable to record stock release.';}}
$agents=$pdo->query("SELECT id,name FROM agents WHERE status='Active' ORDER BY name")->fetchAll();$rows=$pdo->query("SELECT r.*,a.name AS agent_name FROM inventory_releases r JOIN agents a ON a.id=r.agent_id ORDER BY r.released_at DESC,r.id DESC")->fetchAll();
$totals=$pdo->query("SELECT package_kg, SUM(quantity) quantity, SUM(package_kg*quantity) total_kg FROM inventory_releases GROUP BY package_kg ORDER BY package_kg")->fetchAll();
require 'includes/header.php';?><div class="shell"><?php require 'includes/sidebar.php';?><main class="main"><?php require 'includes/topbar.php';?><div class="content"><div class="page-heading"><div><div class="eyebrow">STOCK CONTROL</div><h1>Inventory releases</h1><p>Record tube ice released from the plant to each agent.</p></div></div><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?>
<div class="cards"><?php foreach([1,5,20] as $size):$count=0;foreach($totals as $t){if((float)$t['package_kg']===$size)$count=(int)$t['quantity'];}?><div class="stat"><div class="stat-top"><?=$size?> KG packages <span class="stat-icon">▤</span></div><strong><?=$count?></strong><small>Packages released (all-time)</small></div><?php endforeach;?></div>
<div class="panel"><div class="panel-head"><h2>Record stock release</h2></div><div class="panel-body"><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label>Agent *</label><select name="agent_id" required><option value="">Choose agent</option><?php foreach($agents as $a):?><option value="<?=$a['id']?>"><?=e($a['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Package size *</label><select name="package_kg" required><option value="20">20 KG — Sack</option><option value="5">5 KG — Big plastic</option><option value="1">1 KG — Small plastic</option></select></div><div class="field"><label>Number of packages *</label><input type="number" name="quantity" min="1" required></div><div class="field"><label>Release date *</label><input type="date" name="released_at" value="<?=date('Y-m-d')?>" required></div><div class="field full"><label>Notes</label><input name="notes" maxlength="255" placeholder="Optional details"></div><div class="field full"><button class="btn">＋ Record release</button></div></form></div></div>
<div class="panel"><div class="panel-head"><h2>Release history</h2></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Agent</th><th>Packaging</th><th>Packages</th><th>Total KG</th><th>Notes</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty">No stock releases recorded.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=e($r['released_at'])?></td><td><?=e($r['agent_name'])?></td><td><?=e($r['package_kg'])?> KG</td><td><?=e($r['quantity'])?></td><td><?=number_format((float)$r['package_kg']*(int)$r['quantity'],2)?> KG</td><td><?=e($r['notes']?:'—')?></td></tr><?php endforeach;?></tbody></table></div></div>
</div><?php require 'includes/footer.php';?></main></div>
